#nullable enable

using Campaigns.Contracts;
using Campaigns.Views;
using Marten;
using Npgsql;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GIVEN/THEN cells, NOT from the implementation. Pattern: view. Status: ready.
/// Owned by backend-agent. No WHEN: a read model only reads events that already exist.
///
/// SAME EVENTS AS MessageStatus, SAME <c>identity="messageId"</c>, DIFFERENT ROW SHAPE — and having both in
/// one model is the point rather than an accident. The drawing for the two views is identical; nothing in the
/// model distinguishes a JSONB document you load by id from columns you answer with GROUP BY. So these two
/// GTs and MessageStatus's three are the same assertions about the same grain, and the only difference
/// visible in the test code is that these ones are written in SQL.
///
/// There is no <c>MessageMetrics</c> C# type to load: the read model IS the table (a
/// <c>FlatTableProjection</c>, recipe 6), and a class mirroring it would be a second place the schema lives.
/// A reader queries it; so does this file.
///
/// WHAT THE MODEL DECLARES AND THIS RECIPE CANNOT HOLD: <c>recipientCount</c>. It is a count of the
/// recipients array, and <c>FlatTableProjection.Map</c> takes a MEMBER — the declarative API has no compute
/// step. So no assertion below mentions it, and that absence is a measured gap between a model and a recipe
/// rather than an omission in either. The count is answered from DeliveryLog or MessageStatus instead; see
/// finding #4 in the folder README.
/// </summary>
public sealed class MessageMetricsTests(AppFixture fixture) : IntegrationContext(fixture)
{
    /// <summary>One row of the flat table, read as any consumer would read it.</summary>
    private sealed record MetricsRow(Guid CampaignId, Guid SenderId, DateTime QueuedAt, long Delivered, long Bounced);

    private Task Queued(Guid messageId, params string[] recipients) =>
        Given(messageId, new MessageQueued(
            messageId, SeedData.CampaignId, QueueMessageTests.SenderId, "January newsletter",
            recipients, SeedData.SeededAt));

    /// <summary>
    /// The read side of a flat table is SQL, and the column names have to be spelled the same way the
    /// projection spells them — which is why MessageMetricsProjection names every column explicitly instead
    /// of leaning on Marten's snake_case convention. A silent rename between the two shows up only as a
    /// column-not-found at runtime.
    /// </summary>
    private async Task<MetricsRow?> Row(Guid messageId)
    {
        await using var session = Store.QuerySession();
        await using var command = session.Connection!.CreateCommand();
        command.CommandText = $"""
            select campaign_id, sender_id, queued_at, delivered, bounced
            from campaigns.{MessageMetricsProjection.TableName}
            where id = $1
            """;
        command.Parameters.Add(new NpgsqlParameter { Value = messageId });

        await using var reader = await command.ExecuteReaderAsync();
        if (!await reader.ReadAsync()) return null;

        return new MetricsRow(
            reader.GetFieldValue<Guid>(0),
            reader.GetFieldValue<Guid>(1),
            reader.GetFieldValue<DateTime>(2),
            Convert.ToInt64(reader.GetValue(3)),
            Convert.ToInt64(reader.GetValue(4)));
    }

    // metrics start at zero for a queued message
    //   GIVEN MessageQueued
    //   THEN  MessageMetrics
    [Fact]
    public async Task MetricsStartAtZeroForAQueuedMessage()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, "a@example.com", "b@example.com");

        var row = await Row(messageId);

        // ONE ROW PER MESSAGE, and it exists after the queue event alone. MessageQueued is the only event
        // that populates every non-primary-key column, so it is the only one Marten can generate an INSERT
        // for — the row's existence here is what the other two events depend on.
        row.ShouldNotBeNull();

        row.CampaignId.ShouldBe(SeedData.CampaignId);
        row.SenderId.ShouldBe(QueueMessageTests.SenderId);

        // queued_at is mapped from the PAYLOAD, so it is the business time. SenderMonthly keys its month off
        // the event envelope instead and therefore answers a subtly different question — the two choices sit
        // side by side in this project on purpose.
        row.QueuedAt.ShouldBe(SeedData.SeededAt.UtcDateTime);

        // SetValue(0), not "left null". A counter column that started null would make every later Increment
        // a no-op and the report would read empty rather than wrong.
        row.Delivered.ShouldBe(0);
        row.Bounced.ShouldBe(0);
    }

    // outcomes accumulate onto the message's metrics
    //   GIVEN MessageQueued, MessageDelivered, MessageBounced
    //   THEN  MessageMetrics
    [Fact]
    public async Task OutcomesAccumulateOntoTheMessageSMetrics()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, "a@example.com", "b@example.com");

        var before = await Row(messageId);
        before.ShouldNotBeNull();

        await Given(messageId,
            new MessageDelivered(messageId, "a@example.com", SeedData.SeededAt),
            new MessageBounced(messageId, "b@example.com", "mailbox full", SeedData.SeededAt));

        var after = await Row(messageId);
        after.ShouldNotBeNull();

        // COUNTED SEPARATELY, exactly as in MessageStatus — two events, two columns. Here each is a SQL
        // Increment rather than a field of a folded document, which is the only difference the recipe makes
        // to this assertion.
        after.Delivered.ShouldBe(1);
        after.Bounced.ShouldBe(1);

        // AND THE PARTIAL-MAPPING EVENTS DID NOT DISTURB THE REST OF THE ROW. Neither outcome maps
        // campaign_id, sender_id or queued_at, so Marten generates an UPDATE-only function for them: they
        // cannot create a half-filled row, and they cannot blank the columns they say nothing about.
        // Asserted against the before values rather than against constants, because "unchanged" is a claim
        // about a difference.
        after.ShouldBe(before with { Delivered = 1, Bounced = 1 });
    }
}
